export function normalizeRows(rows) {
  const result = [];
  for (const row of rows) {
    if (row == null) continue;
    const id = String(row.id);
    const text = String(row.text);
    result.push({ id, text, length: Buffer.byteLength(text, 'utf8') });
  }
  result.sort((a, b) => a.id.localeCompare(b.id));
  return result;
}

from __future__ import annotations
from dataclasses import dataclass
from typing import Iterable

@dataclass(frozen=True)
class Result:
    name: str
    value: float

def compute(values: Iterable[float]) -> Result:
    total = sum(values)
    count = sum(1 for _ in values)
    return Result(name='mean', value=total / max(count, 1))

from __future__ import annotations
from dataclasses import dataclass
from typing import Iterable

@dataclass(frozen=True)
class Result:
    name: str
    value: float

def compute(values: Iterable[float]) -> Result:
    ordered = sorted(values)
    middle = len(ordered) // 2
    return Result(name='median', value=ordered[middle] if ordered else 0.0)

def validate_manifest(manifest):
    required = {'schema_version', 'records', 'sha256'}
    missing = required.difference(manifest)
    if missing:
        raise ValueError(f'missing fields: {sorted(missing)}')
    if len(manifest['sha256']) != 64:
        raise ValueError('invalid manifest digest')
    return manifest

def validate_source(source):
    if source.get('training_allowed') is not True:
        raise PermissionError('source is not approved for training')
    if not source.get('evidence_refs'):
        raise ValueError('rights evidence is required')
    if source.get('version') is None:
        raise ValueError('source version is required')
    return source

async function handleRequest(req, db) {
  const user = await requireUser(req);
  const payload = await req.json();
  validatePayload(payload);
  const tx = await db.begin();
  try {
    const record = await tx.insert('documents', { owner: user.id, title: payload.title, body: payload.body });
    await tx.commit();
    return Response.json({ id: record.id, title: record.title, body: record.body }, { status: 201 });
  } catch (error) {
    await tx.rollback();
    throw error;
  }
}

